static boolean sameShape(String s, String t) {
    if (s.length() != t.length()) return false;
    int[] toT = new int[128], toS = new int[128];
    Arrays.fill(toT, -1);
    Arrays.fill(toS, -1);
    for (int i = 0; i < s.length(); i++) {
        char a = s.charAt(i), b = t.charAt(i);
        if (toT[a] == -1) toT[a] = b;
        else if (toT[a] != b) return false;
        if (toS[b] == -1) toS[b] = a;
        else if (toS[b] != a) return false;
    }
    return true;
}

